// Initialize execution session
const plan = $('Parse Plan').item.json;
const sessionId = plan.session_id;

// Create shared context for agent collaboration
const sharedContext = {
  session_id: sessionId,
  user_intent: plan.user_intent,
  current_task: 0,
  total_tasks: plan.tasks.length,
  completed_tasks: [],
  failed_tasks: [],
  agent_results: {},
  shared_data: {},
  status: 'executing',
  started_at: new Date().toISOString()
};

// Store in workflow static data for persistence
$setWorkflowStaticData('sharedContext', sharedContext);

// Prepare task queue
const taskQueue = plan.tasks.map((task, index) => ({
  ...task,
  index,
  status: 'pending',
  attempt: 0,
  max_retries: task.retry_count || 3
}));

return {
  plan,
  sharedContext,
  taskQueue,
  currentTaskIndex: 0
};

// Dependency checker and task preparation
const currentTask = $input.item.json;
const sharedContext = $getWorkflowStaticData('sharedContext');

// Check if dependencies are met
if (currentTask.depends_on && currentTask.depends_on.length > 0) {
  const unmetDependencies = currentTask.depends_on.filter(depId => 
    !sharedContext.completed_tasks.includes(depId)
  );

  if (unmetDependencies.length > 0) {
    return {
      ...currentTask,
      status: 'waiting_dependencies',
      unmet_dependencies: unmetDependencies,
      wait_time: 5000
    };
  }
}

// Prepare task context with shared data
const taskContext = {
  ...currentTask,
  shared_context: sharedContext.shared_data,
  previous_results: sharedContext.agent_results,
  session_metadata: {
    session_id: sharedContext.session_id,
    user_intent: sharedContext.user_intent,
    task_number: sharedContext.current_task + 1,
    total_tasks: sharedContext.total_tasks
  },
  status: 'ready',
  prepared_at: new Date().toISOString()
};

return taskContext;

// GENSPARK Agent with fallback to Manus automation
const task = $input.item.json;

// Since GenSpark API may not be available, use Manus as automation fallback
const fallbackTask = {
  agent: 'MANUS',
  fallback_for: 'GENSPARK',
  original_task: task,
  automation_strategy: 'web_interface',
  description: `Automate GenSpark AI task: ${task.description}`,
  automation_steps: [
    'Navigate to genspark.ai',
    'Wait for page load (5 seconds)',
    `Input query: "${task.description}"`,
    'Click generate/search button',
    'Wait for results (30-60 seconds)',
    'Extract and format results',
    'Return structured output'
  ],
  web_config: {
    url: 'https://genspark.ai',
    selectors: {
      input: 'textarea, input[type="text"]',
      submit: 'button[type="submit"], .generate-btn',
      results: '.result, .output, .response'
    },
    timeouts: {
      page_load: 5000,
      generation: 60000,
      extraction: 10000
    }
  },
  shared_context: task.shared_context,
  previous_results: task.previous_results,
  session_metadata: task.session_metadata,
  timeout_seconds: task.timeout_seconds || 300,
  max_retries: task.max_retries || 3
};

return fallbackTask;

