// Agent result processor and context updater
const agentResult = $input.item.json;
const originalTask = $('Check Dependencies').item.json;
const sharedContext = $getWorkflowStaticData('sharedContext');

// Process different agent response formats
let processedResult;
try {
  if (agentResult.choices && agentResult.choices[0]) {
    // OpenAI format (MVP Agent)
    processedResult = {
      agent: originalTask.agent,
      task_id: originalTask.id,
      status: 'completed',
      output: agentResult.choices[0].message.content,
      raw_response: agentResult,
      completed_at: new Date().toISOString()
    };
  } else if (agentResult.result || agentResult.output) {
    // Standard API format
    processedResult = {
      agent: originalTask.agent,
      task_id: originalTask.id,
      status: 'completed',
      output: agentResult.result || agentResult.output,
      raw_response: agentResult,
      completed_at: new Date().toISOString()
    };
  } else {
    // Direct result format
    processedResult = {
      agent: originalTask.agent,
      task_id: originalTask.id,
      status: 'completed',
      output: agentResult,
      completed_at: new Date().toISOString()
    };
  }
} catch (error) {
  processedResult = {
    agent: originalTask.agent,
    task_id: originalTask.id,
    status: 'error',
    error: error.message,
    output: null,
    completed_at: new Date().toISOString()
  };
}

// Update shared context
sharedContext.agent_results[originalTask.agent] = processedResult.output;
sharedContext.completed_tasks.push(originalTask.id);
sharedContext.current_task++;

// Store updated context
$setWorkflowStaticData('sharedContext', sharedContext);

return {
  ...processedResult,
  shared_context_updated: true,
  total_completed: sharedContext.completed_tasks.length,
  remaining_tasks: sharedContext.total_tasks - sharedContext.completed_tasks.length
};

// Comprehensive error recovery system
const errorResult = $input.item.json;
const originalTask = $('Check Dependencies').item.json;
const sharedContext = $getWorkflowStaticData('sharedContext');

// Get current retry count
const currentRetries = sharedContext.retry_counts?.[originalTask.id] || 0;
const maxRetries = originalTask.max_retries || 3;

// Initialize retry tracking
if (!sharedContext.retry_counts) {
  sharedContext.retry_counts = {};
}

if (currentRetries >= maxRetries) {
  // Max retries exceeded - mark as failed and continue
  sharedContext.failed_tasks.push(originalTask.id);
  sharedContext.current_task++;

  $setWorkflowStaticData('sharedContext', sharedContext);

  return {
    action: 'skip_and_continue',
    reason: 'Max retries exceeded',
    task_id: originalTask.id,
    agent: originalTask.agent,
    error: errorResult.error || 'Unknown error',
    final_status: 'failed_permanently'
  };
}

// Increment retry count
sharedContext.retry_counts[originalTask.id] = currentRetries + 1;
$setWorkflowStaticData('sharedContext', sharedContext);

// Calculate exponential backoff
const backoffTime = Math.min(Math.pow(2, currentRetries) * 1000, 30000); // Max 30 seconds

return {
  action: 'retry',
  task: originalTask,
  attempt: currentRetries + 1,
  max_attempts: maxRetries,
  backoff_time: backoffTime,
  error_context: errorResult
};

// Generate comprehensive final response
const sharedContext = $getWorkflowStaticData('sharedContext');
const plan = $('Parse Plan').item.json;

// Calculate execution statistics
const totalTasks = sharedContext.total_tasks;
const completedTasks = sharedContext.completed_tasks.length;
const failedTasks = sharedContext.failed_tasks?.length || 0;
const successRate = Math.round((completedTasks / totalTasks) * 100);

// Gather all agent results
const agentResults = sharedContext.agent_results || {};

// Calculate total execution time
const startTime = new Date(sharedContext.started_at);
const endTime = new Date();
const executionTimeMs = endTime.getTime() - startTime.getTime();
const executionTimeSeconds = Math.round(executionTimeMs / 1000);

// Create comprehensive response
const finalResponse = {
  session_id: sharedContext.session_id,
  user_intent: sharedContext.user_intent,
  execution_summary: {
    status: failedTasks > 0 ? 'partial_success' : 'success',
    total_tasks: totalTasks,
    completed_tasks: completedTasks,
    failed_tasks: failedTasks,
    success_rate: successRate,
    execution_time_seconds: executionTimeSeconds
  },
  agent_results: agentResults,
  task_details: plan.tasks.map(task => ({
    id: task.id,
    agent: task.agent,
    description: task.description,
    status: sharedContext.completed_tasks.includes(task.id) ? 'completed' : 
            sharedContext.failed_tasks?.includes(task.id) ? 'failed' : 'pending',
    result: agentResults[task.agent] || null
  })),
  coordination_notes: plan.coordination_notes,
  completed_at: new Date().toISOString(),

  // User-friendly summary
  summary: `Successfully completed ${completedTasks}/${totalTasks} tasks in ${executionTimeSeconds} seconds with ${successRate}% success rate.`,

  // Next steps recommendations
  recommendations: failedTasks > 0 ? [
    'Review failed tasks for potential retry',
    'Consider adjusting task complexity or timeout settings',
    'Check agent-specific error logs for troubleshooting'
  ] : [
    'All tasks completed successfully',
    'Results are available for further processing',
    'System ready for next orchestration request'
  ]
};

// Clear workflow static data for next execution
$setWorkflowStaticData('sharedContext', null);
$setWorkflowStaticData('results', null);

return finalResponse;

